from bisect import bisect_left


def earliest_arrival(n: int, connections: list[tuple[int, int, int, int]], source: int, target: int, start: int, change: int, max_transfers: int) -> int:
    if source == target:
        return start
    INF = 1 << 62
    grouped = {}
    for u, v, dep, arr_t in connections:
        lst = grouped.get(u)
        if lst is None:
            grouped[u] = [(dep, arr_t, v)]
        else:
            lst.append((dep, arr_t, v))
    deps_of = {}
    for u, lst in grouped.items():
        lst.sort()
        deps_of[u] = [item[0] for item in lst]

    best = [INF] * n
    frontier = [source]
    first = True
    for _level in range(max_transfers + 1):
        if not frontier:
            break
        updates = {}
        bound = best[target]
        for u in frontier:
            lst = grouped.get(u)
            if lst is None:
                continue
            if first:
                ready = start
            else:
                if u == source:
                    # 出発時の状態（時刻 start・乗車 0 本）が常に優越する
                    continue
                ready = best[u] + change
            idx = bisect_left(deps_of[u], ready)
            for pos in range(idx, len(lst)):
                _dep, arr_t, v = lst[pos]
                if arr_t < best[v] and arr_t < bound:
                    prev = updates.get(v)
                    if prev is None or arr_t < prev:
                        updates[v] = arr_t
        first = False
        for v, t in updates.items():
            best[v] = t
        frontier = list(updates)

    result = best[target]
    return result if result < INF else -1
